public sealed record Result<T>(T? Value, IReadOnlyList<string> Errors)
{
    public static Result<T> Success(T value)
        => new(value, []);

    public static Result<T> Failure(IEnumerable<string> errors)
        => new(default, [.. errors]);

    public bool IsSuccess => Errors.Count == 0;
}

