public class ValidationPipelineBehavior<TRequest, TResponse>
    : IPipelineBehavior<TRequest, TResponse>
    where TRequest : IRequest<TResponse>
{
    private readonly IEnumerable<IValidator<TRequest>> _validators;

    public ValidationPipelineBehavior(IEnumerable<IValidator<TRequest>> validators)
    {
        _validators = validators;
    }

    public async Task<TResponse> Handle(TRequest request, RequestHandlerDelegate<TResponse> next, CancellationToken ct)
    {
        if (!_validators.Any())
            return await next();

        var context = new ValidationContext<TRequest>(request);
        var results = await Task.WhenAll(
            _validators.Select(v => v.ValidateAsync(context, ct)));

        var failures = results
            .SelectMany(r => r.Errors)
            .Where(f => f is not null)
            .ToList();

        if (failures.Count > 0)
        {
            var errors = failures.Select(f => f.ErrorMessage).ToList();
            if (typeof(TResponse).IsGenericType && typeof(TResponse).GetGenericTypeDefinition() == typeof(Result<>))
            {
                var resultType = typeof(Result<>).MakeGenericType(typeof(TResponse).GenericTypeArguments[0]);
                var failureMethod = resultType.GetMethod(nameof(Result<Guid>.Failure))!;
                var failureResult = failureMethod.Invoke(null, [errors])!;
                return (TResponse)failureResult;
            }

            throw new ValidationException(failures);
        }

        return await next();
    }
}

public class SubmitExpenseReportValidator : AbstractValidator<SubmitExpenseReportCommand>
{
    public SubmitExpenseReportValidator()
    {
        RuleFor(x => x.OrganizationId).NotEmpty();
        RuleFor(x => x.EmployeeId).NotEmpty();
        RuleFor(x => x.LineItems).NotEmpty().WithMessage("A report must contain at least one line item.");

        RuleForEach(x => x.LineItems).ChildRules(item =>
        {
            item.RuleFor(x => x.Amount.Amount).GreaterThan(0).WithMessage("Amount must be positive.");
            item.RuleFor(x => x.Date)
                .LessThanOrEqualTo(DateOnly.FromDateTime(DateTime.UtcNow))
                .WithMessage("Line items cannot be dated in the future.");
            item.RuleFor(x => x.Description)
                .MaximumLength(500).When(x => !string.IsNullOrWhiteSpace(x.Description));
        });

        RuleFor(x => x.LineItems)
            .Must(items => items.Count <= 50)
            .WithMessage("A single report cannot exceed 50 line items.");
    }
}

public class GlobalExceptionHandler(IProblemDetailsService pds, ILogger<GlobalExceptionHandler> log)
    : ExceptionHandlerMiddleware
{
    public override async Task TryHandleAsync(HttpContext ctx, Exception ex, CancellationToken ct)
    {
        log.LogError(ex, "Unhandled exception: {Message}", ex.Message);

        var (status, title, detail) = ex switch
        {
            ValidationException vex => (StatusCodes.Status422UnprocessableEntity, "Validation Failed", vex.Message),
            DomainException dex => (StatusCodes.Status400BadRequest, "Business Rule Violation", dex.Message),
            NotFoundException _ => (StatusCodes.Status404NotFound, "Not Found", ex.Message),
            _ => (StatusCodes.Status500InternalServerError, "Server Error", "An unexpected error occurred.")
        };

        ctx.Response.StatusCode = status;
        ctx.Response.ContentType = "application/problem+json";

        var problem = new ProblemDetailsContext
        {
            HttpContext = ctx,
            ProblemDetails =
            {
                Status = status,
                Title = title,
                Detail = detail,
                Type = ex.GetType().FullName,
                Instance = ctx.Request.Path,
            }
        };

        await pds.WriteAsync(problem);
        return true;
    }
}
